    font-size: 14px;
    font-weight: 600;
    color: #fff;
    background: var(--primary);
    border-radius: 20px;
    text-decoration: none;
    transition: all 0.2s;
    white-space: nowrap;
}

.navbar-sponsor:hover {
    background: var(--primary-hover);
    color: #fff;
    text-decoration: none;
}

.navbar-right {
    display: flex;
    align-items: center;
    gap: 16px;
}

.user-info {
