            },
            `????????`
        );

        // ??????
        await GitHubAPI.updateJsonData(
            CONFIG.DATA.USERS,
            (data) => {
                if (!data.users) data.users = [];
                data.users = data.users.filter(u => u.id !== userId);
                return data;
            },
            `??????`
        );

        return { success: true, message: '????????????????' };
    },

    // ???????????
    async _setUserStatus(userId, status, label, reason = '') {
        const currentUser = this.getCurrentUserLocal();
        if (currentUser.id === userId) throw new Error(`??${label}?????`);
        const currentRole = currentUser.role || 'user';

        await GitHubAPI.updateJsonData(
            CONFIG.DATA.USERS,
            (data) => {
                if (!data.users) data.users = [];
                const user = data.users.find(u => u.id === userId);
                if (!user) throw new Error('?????');
                const targetRole = user.role || 'user';

                // ??????????
                if (targetRole === 'superadmin') throw new Error(`??${label}???????`);
                // ?????????????????????????
                if (currentRole === 'admin' && targetRole !== 'user') throw new Error(`??${label}?????`);
                // ?????????
                if (currentRole !== 'admin' && currentRole !== 'superadmin') throw new Error('?????');

                user.status = status;
                user.statusReason = reason || '';
                user.statusUpdatedAt = new Date().toISOString();
                user.statusUpdatedBy = currentUser.username;
                return data;
            },
            `???${label}??: ${userId}`
        );

        // ??????????
        await GitHubAPI.updateJsonData(
            CONFIG.DATA.SESSIONS,
            (data) => {
                if (!data.sessions) data.sessions = [];
                data.sessions = data.sessions.filter(s => s.userId !== userId);
                return data;
            },
            `???${label}??????`
        );
    }
};

